-- Mob AI: race rules (dragon / demon breath, sweep, roar), WP-D of ops/plans/mob-ai.md.
--
-- Legacy dragonlike_attack (mobact.cpp): roll = rand(0, 150 - level); breath if roll < 5, sweep if
-- roll < 10, roar if roll < 15, for the DRAGON_* / DRAGONBORN_* races and DEMON. The element comes
-- from the body composition (earth/stone acid, air/ether lightning, fire/lava fire, water/ice/mist
-- frost, metal/bone/plant gas), any other composition rolls it. The rules express the bands with the
-- level_roll condition (one shared roll per mob per round) and the element with composition /
-- not_composition. min_level keeps a low-level demon from breathing, sweeping or roaring.
--
--   1. creates "RaceAiRules" or adds its min_level / seed_key / seed_hash columns (matches muditor
--      packages/db/prisma/schema.prisma, db push compatible),
--   2. adds the RaceAbilities rows the races lack (legacy races.cpp assign_race_skills): the DRAGON_*
--      races and DEMON had no BREATHE_* / SWEEP / ROAR row; DRAGONBORN_* already have their breath,
--   3. seeds the rules.
-- Generated by `python -m fierylib.seeders.mob_ai_seeder --write-sql` from data/mob_ai_seed.json; a
-- unit test keeps the two in sync. Standalone (own table); the server loads it at every boot but uses
-- it only with mob_ai.enabled on. Keyed by Races.race (enum) and Ability.plain_name, never numeric ids.
--
-- Ownership: each rule has a stable seed_key and a seed_hash of the values it last wrote. Step 3
-- (a) claims existing un-keyed rows that still match the seed, (b) upserts on seed_key, updating a
-- row only while its stored hash equals the hash of its current values, so a builder-edited row
-- (hash cleared or stale) is left alone, and (c) disables seed-owned rows whose key left the seed.
-- A second run changes 0 rows.

BEGIN;

CREATE TABLE IF NOT EXISTS "RaceAiRules" (
    "id" SERIAL NOT NULL,
    "race" "Race" NOT NULL,
    "ability_id" INTEGER NOT NULL,
    "priority" INTEGER NOT NULL,
    "chance_pct" INTEGER NOT NULL DEFAULT 100,
    "cooldown_s" INTEGER NOT NULL DEFAULT 0,
    "conditions" JSONB,
    "target" TEXT NOT NULL,
    "min_level" INTEGER,
    "enabled" BOOLEAN NOT NULL DEFAULT true,
    "seed_key" TEXT,
    "seed_hash" TEXT,

    CONSTRAINT "RaceAiRules_pkey" PRIMARY KEY ("id")
);

-- A table created by an earlier version of this patch lacks the newer columns.
ALTER TABLE "RaceAiRules"
    ADD COLUMN IF NOT EXISTS "min_level" INTEGER,
    ADD COLUMN IF NOT EXISTS "seed_key" TEXT,
    ADD COLUMN IF NOT EXISTS "seed_hash" TEXT;

CREATE INDEX IF NOT EXISTS "RaceAiRules_race_idx" ON "RaceAiRules"("race");

CREATE UNIQUE INDEX IF NOT EXISTS "RaceAiRules_race_ability_id_priority_key"
    ON "RaceAiRules"("race", "ability_id", "priority");

CREATE UNIQUE INDEX IF NOT EXISTS "RaceAiRules_seed_key_key" ON "RaceAiRules"("seed_key");

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'RaceAiRules_race_fkey') THEN
        ALTER TABLE "RaceAiRules" ADD CONSTRAINT "RaceAiRules_race_fkey"
            FOREIGN KEY ("race") REFERENCES "Races"("race") ON DELETE CASCADE ON UPDATE CASCADE;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'RaceAiRules_ability_id_fkey') THEN
        ALTER TABLE "RaceAiRules" ADD CONSTRAINT "RaceAiRules_ability_id_fkey"
            FOREIGN KEY ("ability_id") REFERENCES "Ability"("id") ON DELETE CASCADE ON UPDATE CASCADE;
    END IF;
END
$$;

INSERT INTO "RaceAbilities" (race, ability_id, category, bonus, proficiency_cap)
SELECT v.race::"Race", a.id, 'PRIMARY', 0, 100
FROM (VALUES
    ('DRAGON_GENERAL', 'BREATHE_FIRE'),
    ('DRAGON_GENERAL', 'BREATHE_GAS'),
    ('DRAGON_GENERAL', 'BREATHE_FROST'),
    ('DRAGON_GENERAL', 'BREATHE_ACID'),
    ('DRAGON_GENERAL', 'BREATHE_LIGHTNING'),
    ('DRAGON_GENERAL', 'SWEEP'),
    ('DRAGON_GENERAL', 'ROAR'),
    ('DEMON', 'BREATHE_FIRE'),
    ('DEMON', 'BREATHE_GAS'),
    ('DEMON', 'BREATHE_FROST'),
    ('DEMON', 'BREATHE_ACID'),
    ('DEMON', 'BREATHE_LIGHTNING'),
    ('DEMON', 'ROAR'),
    ('DRAGON_FIRE', 'BREATHE_FIRE'),
    ('DRAGON_FIRE', 'SWEEP'),
    ('DRAGON_FIRE', 'ROAR'),
    ('DRAGON_FROST', 'BREATHE_FROST'),
    ('DRAGON_FROST', 'SWEEP'),
    ('DRAGON_FROST', 'ROAR'),
    ('DRAGON_ACID', 'BREATHE_ACID'),
    ('DRAGON_ACID', 'SWEEP'),
    ('DRAGON_ACID', 'ROAR'),
    ('DRAGON_GAS', 'BREATHE_GAS'),
    ('DRAGON_GAS', 'SWEEP'),
    ('DRAGON_GAS', 'ROAR'),
    ('DRAGON_LIGHTNING', 'BREATHE_LIGHTNING'),
    ('DRAGON_LIGHTNING', 'SWEEP'),
    ('DRAGON_LIGHTNING', 'ROAR')
) AS v(race, ability_name)
JOIN "Ability" a ON a.plain_name = v.ability_name
ON CONFLICT (race, ability_id) DO NOTHING;

