    ('DRAGON_LIGHTNING', 'DRAGON_LIGHTNING:BREATHE_LIGHTNING', 'BREATHE_LIGHTNING', 10, 100, 0, '{"in_combat": true, "level_roll": {"max": 5, "min": 0}}', 'auto', 15),
