    ('DRAGON_GENERAL', 'DRAGON_GENERAL:BREATHE_FROST', 'BREATHE_FROST', 12, 100, 0, '{"composition": ["WATER", "ICE", "MIST"], "in_combat": true, "level_roll": {"max": 5, "min": 0}}', 'auto', 15),
