    ('DEMON', 'DEMON:BREATHE_FROST', 'BREATHE_FROST', 12, 100, 0, '{"composition": ["WATER", "ICE", "MIST"], "in_combat": true, "level_roll": {"max": 5, "min": 0}}', 'auto', 15),
    ('DEMON', 'DEMON:BREATHE_ACID', 'BREATHE_ACID', 13, 100, 0, '{"composition": ["EARTH", "STONE"], "in_combat": true, "level_roll": {"max": 5, "min": 0}}', 'auto', 15),
    ('DEMON', 'DEMON:BREATHE_LIGHTNING', 'BREATHE_LIGHTNING', 14, 100, 0, '{"composition": ["AIR", "ETHER"], "in_combat": true, "level_roll": {"max": 5, "min": 0}}', 'auto', 15),
