    ('DEMON', 'DEMON:BREATHE_GAS:other', 'BREATHE_GAS', 21, 100, 0, '{"in_combat": true, "level_roll": {"max": 2, "min": 1}, "not_composition": ["AIR", "BONE", "EARTH", "ETHER", "FIRE", "ICE", "LAVA", "METAL", "MIST", "PLANT", "STONE", "WATER"]}', 'auto', 15),
    ('DEMON', 'DEMON:BREATHE_FROST:other', 'BREATHE_FROST', 22, 100, 0, '{"in_combat": true, "level_roll": {"max": 3, "min": 2}, "not_composition": ["AIR", "BONE", "EARTH", "ETHER", "FIRE", "ICE", "LAVA", "METAL", "MIST", "PLANT", "STONE", "WATER"]}', 'auto', 15),
    ('DEMON', 'DEMON:BREATHE_ACID:other', 'BREATHE_ACID', 23, 100, 0, '{"in_combat": true, "level_roll": {"max": 4, "min": 3}, "not_composition": ["AIR", "BONE", "EARTH", "ETHER", "FIRE", "ICE", "LAVA", "METAL", "MIST", "PLANT", "STONE", "WATER"]}', 'auto', 15),
    ('DEMON', 'DEMON:BREATHE_LIGHTNING:other', 'BREATHE_LIGHTNING', 24, 100, 0, '{"in_combat": true, "level_roll": {"max": 5, "min": 4}, "not_composition": ["AIR", "BONE", "EARTH", "ETHER", "FIRE", "ICE", "LAVA", "METAL", "MIST", "PLANT", "STONE", "WATER"]}', 'auto', 15),
    ('DEMON', 'DEMON:ROAR', 'ROAR', 50, 100, 0, '{"in_combat": true, "level_roll": {"max": 15, "min": 10}}', 'auto', 25)
), raw AS (
    SELECT rr.race::"Race" AS race, rr.rule_key AS seed_key, a.id AS ability_id, rr.priority::int AS priority,
           rr.chance_pct::int AS chance_pct, rr.cooldown_s::int AS cooldown_s,
           rr.conditions::jsonb AS conditions, rr.target AS target, rr.min_level::int AS min_level
    FROM race_rule rr
    JOIN "Ability" a ON a.plain_name = rr.ability_name
    JOIN "RaceAbilities" ra ON ra.race = rr.race::"Race" AND ra.ability_id = a.id
), seed AS (
    SELECT raw.*, md5(concat_ws('|', raw.ability_id, raw.priority, raw.chance_pct, raw.cooldown_s, coalesce(raw.conditions::text, ''), raw.target, coalesce(raw.min_level::text, ''))) AS seed_hash FROM raw
)
UPDATE "RaceAiRules" r SET seed_key = s.seed_key, seed_hash = md5(concat_ws('|', r.ability_id, r.priority, r.chance_pct, r.cooldown_s, coalesce(r.conditions::text, ''), r.target, coalesce(r.min_level::text, '')))
FROM seed s
WHERE r.seed_key IS NULL AND r.race = s.race AND r.ability_id = s.ability_id
  AND r.priority = s.priority AND r.chance_pct = s.chance_pct
  AND r.conditions IS NOT DISTINCT FROM s.conditions AND r.target = s.target
  AND (r.cooldown_s = s.cooldown_s OR r.cooldown_s = 0)
  AND (r.min_level IS NOT DISTINCT FROM s.min_level OR r.min_level IS NULL)
  AND NOT EXISTS (SELECT 1 FROM "RaceAiRules" k WHERE k.seed_key = s.seed_key);

