    ('DEMON', 'DEMON:ROAR', 'ROAR', 50, 100, 0, '{"in_combat": true, "level_roll": {"max": 15, "min": 10}}', 'auto', 25)
), raw AS (
    SELECT rr.race::"Race" AS race, rr.rule_key AS seed_key, a.id AS ability_id, rr.priority::int AS priority,
           rr.chance_pct::int AS chance_pct, rr.cooldown_s::int AS cooldown_s,
           rr.conditions::jsonb AS conditions, rr.target AS target, rr.min_level::int AS min_level
    FROM race_rule rr
    JOIN "Ability" a ON a.plain_name = rr.ability_name
    JOIN "RaceAbilities" ra ON ra.race = rr.race::"Race" AND ra.ability_id = a.id
), seed AS (
    SELECT raw.*, md5(concat_ws('|', raw.ability_id, raw.priority, raw.chance_pct, raw.cooldown_s, coalesce(raw.conditions::text, ''), raw.target, coalesce(raw.min_level::text, ''))) AS seed_hash FROM raw
)
INSERT INTO "RaceAiRules" (race, ability_id, priority, chance_pct, cooldown_s, conditions,
    target, min_level, enabled, seed_key, seed_hash)
SELECT s.race, s.ability_id, s.priority, s.chance_pct, s.cooldown_s, s.conditions,
       s.target, s.min_level, true, s.seed_key, s.seed_hash
FROM seed s
WHERE NOT EXISTS (SELECT 1 FROM "RaceAiRules" x WHERE x.race = s.race AND x.ability_id = s.ability_id
                  AND x.priority = s.priority AND x.seed_key IS DISTINCT FROM s.seed_key)
ON CONFLICT (seed_key) DO UPDATE SET
    race = EXCLUDED.race, ability_id = EXCLUDED.ability_id, priority = EXCLUDED.priority,
    chance_pct = EXCLUDED.chance_pct, cooldown_s = EXCLUDED.cooldown_s, conditions = EXCLUDED.conditions,
    target = EXCLUDED.target, min_level = EXCLUDED.min_level, seed_hash = EXCLUDED.seed_hash
WHERE "RaceAiRules".seed_hash IS NOT DISTINCT FROM md5(concat_ws('|', "RaceAiRules".ability_id, "RaceAiRules".priority, "RaceAiRules".chance_pct, "RaceAiRules".cooldown_s, coalesce("RaceAiRules".conditions::text, ''), "RaceAiRules".target, coalesce("RaceAiRules".min_level::text, '')))
  AND "RaceAiRules".seed_hash IS DISTINCT FROM EXCLUDED.seed_hash;

