)
UPDATE "RaceAiRules" r SET enabled = false
WHERE r.seed_key IS NOT NULL AND r.enabled AND r.seed_hash IS NOT DISTINCT FROM md5(concat_ws('|', r.ability_id, r.priority, r.chance_pct, r.cooldown_s, coalesce(r.conditions::text, ''), r.target, coalesce(r.min_level::text, '')))
  AND NOT EXISTS (SELECT 1 FROM seed s WHERE s.seed_key = r.seed_key);

COMMIT;
